"""Agreement with JSkyCalc itself (fixtures generated by validation/run_jskycalc.sh).

Tolerances reflect *known* modelling differences, documented in validation/VALIDATION.md:
JSkyCalc uses mean places without nutation/aberration (→ 10–30″ in alt/az), mean sidereal
time, UTC for UT1, its own low-order barycentre model (few m/s), and analytic shortcuts.
"""

import pytest

compare = pytest.importorskip("compare")

TOLERANCES = {
    "LMST [s]": 0.5,
    "LAST vs JSkyCalc LMST [s]": 1.5,          # equation of the equinoxes ≤ 1.2 s
    "Sun alt [arcsec]": 30, "Sun az [arcsec]": 30,  # JSkyCalc Sun lacks annual aberration
    "Moon alt [arcsec]": 15, "Moon az [arcsec]": 15,
    "Moon illuminated fraction": 0.003,
    "Zenith twilight [mag]": 0.005,
    "Moon phase text [days]": 0.11,
    "Sunset [s]": 10, "Sunrise [s]": 10,
    "18° twilight (evening) [s]": 5, "18° twilight (morning) [s]": 5, "Night centre [s]": 5,
    "Moonrise [s]": 15, "Moonset [s]": 15,
    "Hour angle × cos δ [arcsec]": 40, "Hour angle, |δ| < 80° [s]": 8,
    "Altitude [arcsec]": 35, "Azimuth × cos(alt) [arcsec]": 35,
    "Parallactic angle [arcsec]": 300,         # ill-conditioned near the zenith
    "Mean place of date [arcsec]": 1.0,        # FK4→FK5 E-terms for the B1950 entry
    "Galactic l,b [arcsec]": 1.0,
    "Constellation (mismatches)": 0,
    "Moon–object angle [arcsec]": 30,
    "Lunar sky brightness [mag]": 0.002,
    "Bary. JD (UTC-based, JSkyCalc def.) [s]": 0.05, "Bary. light-time [s]": 0.05,
    "Bary. RV correction [m/s]": 10,
    "Parallax factors": 1e-4,
    "Seasonal: evening date (mismatches)": 0, "Seasonal: HA [min]": 1.001,  # both tables round to the minute
    "Seasonal: hours observable [h]": 0.1,
    "Airmass (relative, alt > 10°)": 1e-3, "Airmass (relative, 0° < alt < 10°)": 1e-2,
    "18° twilight: JSkyCalc degenerate cases": 0,
}


@pytest.fixture(scope="module")
def results():
    return compare.compare()


def test_every_quantity_has_a_tolerance(results):
    assert set(results) == set(TOLERANCES), set(results) ^ set(TOLERANCES)


@pytest.mark.parametrize("quantity", sorted(TOLERANCES))
def test_quantity_within_tolerance(results, quantity):
    recs = results[quantity]
    assert recs, f"no comparisons for {quantity}"
    worst = max(recs, key=lambda r: abs(r[4]))
    assert abs(worst[4]) <= TOLERANCES[quantity], f"{quantity}: worst {worst}"
